-- V17: seed three legal pages (Terms of Service, Privacy Policy, Refund
-- Policy) as CMS sections. Every payment gateway (Razorpay, Stripe, PayPal)
-- requires all three pages to be reachable at working URLs before approving
-- the account for live payments.
--
-- Content is TEMPLATE only — it uses placeholders like [YOUR NAME] /
-- [YOUR EMAIL] / [YOUR JURISDICTION]. The site owner MUST edit them under
-- /admin/portfolio → Legal → {tab} before going live, and should have a
-- lawyer review them for their specific business + jurisdiction.
--
-- Shape:
--   title:        page heading
--   lastUpdated:  ISO date (YYYY-MM-DD)
--   body:         markdown-ish body. The frontend LegalPage supports:
--                   ## Heading            → <h2>
--                   ### Sub-heading       → <h3>
--                   - bullet              → <li>
--                   blank line            → new paragraph
--                   **bold**              → <strong>
--
-- Idempotent: each INSERT skips if the key is already present.

INSERT INTO portfolio_content (section_key, label, body)
SELECT 'legal.terms', 'Legal — Terms of Service', '{
  "title": "Terms of Service",
  "lastUpdated": "2026-01-01",
  "body": "**These terms are a template.** Edit under /admin/portfolio → Legal → Terms before your first sale, and have a lawyer familiar with your jurisdiction review them.\n\n## 1. Who we are\n\nThese Terms of Service (\"Terms\") govern your use of the website at [YOUR DOMAIN] (the \"Service\") operated by [YOUR COMPANY / YOUR NAME] (\"we\", \"us\", \"our\"). By accessing or using the Service you agree to be bound by these Terms.\n\n## 2. Digital products\n\nThe Service offers digital products — source code, templates, and related assets — delivered as downloadable files via a private link sent to the email address you provide at checkout.\n\nEach purchase grants you a **non-exclusive, non-transferable, worldwide licence** to use the product for one commercial or personal project owned by you or your direct client. You may not:\n\n- Resell, sublicense, or redistribute the source code or assets\n- Publish them on any code-sharing site (public GitHub repo, Gist, etc.)\n- Use them to train machine-learning models\n- Remove or obscure copyright notices in the source\n\n## 3. Payment\n\nAll payments are processed by Razorpay and (when enabled) Stripe. We do not store your card details on our servers. Prices are shown in the currency you select at checkout and include applicable taxes where required.\n\n## 4. Delivery\n\nDownload links are emailed to the address you provide at checkout, typically within 60 seconds of successful payment. Links are valid for **365 days from the date of purchase**. If your link expires or you lose access to it, email [YOUR SUPPORT EMAIL] and we will re-issue it.\n\n## 5. Refunds\n\nSee our separate [Refund Policy](/legal/refund).\n\n## 6. Intellectual property\n\nAll source code, designs, and content on the Service — with the exception of open-source dependencies clearly attributed in each product — are the property of [YOUR COMPANY / YOUR NAME] and protected by copyright, trademark, and other intellectual property laws.\n\n## 7. Prohibited use\n\nYou may not use the Service to:\n\n- Violate any applicable law or regulation\n- Infringe on the intellectual property rights of others\n- Distribute malware or attempt to compromise the Service\n- Impersonate any person or entity\n- Reverse-engineer the platform itself\n\n## 8. Termination\n\nWe reserve the right to suspend or terminate your access to the Service without notice for any breach of these Terms.\n\n## 9. Limitation of liability\n\nTo the maximum extent permitted by applicable law, the Service and all products are provided **\"as is\" and \"as available\"** without warranties of any kind. In no event shall [YOUR COMPANY / YOUR NAME] be liable for any indirect, incidental, special, consequential, or punitive damages arising from your use of the Service. Our total liability shall not exceed the amount you paid for the specific product giving rise to the claim.\n\n## 10. Changes to these Terms\n\nWe may update these Terms from time to time. When we do, we will change the \"Last updated\" date at the top of this page. Continued use of the Service after any change constitutes your acceptance of the updated Terms.\n\n## 11. Governing law\n\nThese Terms are governed by the laws of [YOUR JURISDICTION — e.g. India, Republic of Estonia, State of Delaware USA]. Any dispute arising under these Terms shall be resolved exclusively in the courts of [YOUR CITY], [YOUR JURISDICTION].\n\n## 12. Contact\n\nQuestions about these Terms? Email [YOUR SUPPORT EMAIL]."
}'
WHERE NOT EXISTS (SELECT 1 FROM portfolio_content WHERE section_key = 'legal.terms');

INSERT INTO portfolio_content (section_key, label, body)
SELECT 'legal.privacy', 'Legal — Privacy Policy', '{
  "title": "Privacy Policy",
  "lastUpdated": "2026-01-01",
  "body": "**This privacy policy is a template.** Edit under /admin/portfolio → Legal → Privacy before your first sale, and consider having it reviewed for GDPR / DPDPA / CCPA compliance depending on where your buyers live.\n\n## 1. Who we are\n\nThis Privacy Policy describes how [YOUR COMPANY / YOUR NAME] (\"we\", \"us\", \"our\") collects, uses, and shares information when you use the Service at [YOUR DOMAIN].\n\n## 2. Information we collect\n\n### 2.1 Information you provide directly\n\n- **Contact form**: name, email, company (optional), project type (optional), message\n- **Checkout**: name, email, purchase details (products bought, currency, amount)\n- **Newsletter** (if signed up): email address\n\n### 2.2 Information collected automatically\n\n- **IP address** — hashed with a per-instance salt on our servers before storage; the raw IP is never persisted\n- **User agent** — the browser + OS your device reports\n- **Timestamps** — when you visited, when you submitted a form\n\n### 2.3 Information we do NOT collect\n\n- Card / payment details — these go directly to our payment processors (Razorpay, Stripe) and never touch our servers\n- Browsing history outside our site\n- Any data from third-party accounts you do not connect to us\n\n## 3. How we use your information\n\n- To deliver the products you purchased (send download links)\n- To respond to messages you send via the contact form\n- To email you about your order (confirmation, receipt, expiry reminders)\n- To detect and prevent fraud, abuse, and rate-limit violations\n- To comply with legal obligations (tax records, dispute resolution)\n\nWe do **not** use your information for third-party advertising, and we do not sell your data.\n\n## 4. Who we share it with\n\n- **Razorpay / Stripe**: payment processors. They receive your email, name, and payment details for the purpose of collecting the payment. Their privacy policies govern their use of that data.\n- **Email provider ([YOUR EMAIL PROVIDER, e.g. SendGrid, Postmark, Amazon SES])**: to send you order confirmations and receipts.\n- **Hosting provider**: our infrastructure is hosted at [YOUR HOSTING PROVIDER]. They see IP addresses of visitors as part of normal server operation.\n\nWe do not share your information with anyone else except when required by law (court order, tax authority request, etc.).\n\n## 5. Cookies\n\nWe use only strictly-necessary cookies (session tokens for admin, cart persistence for shoppers). We do not set analytics or advertising cookies without your explicit consent.\n\nIf we add analytics later (Plausible / GA / Umami), we will update this policy and provide a way to opt out where required by law.\n\n## 6. Data retention\n\n- **Contact submissions**: retained for 24 months, then deleted or anonymised\n- **Orders**: retained for 7 years for tax compliance\n- **Uploaded product images / your CV**: retained until you delete them from the admin panel or your account\n- **IP hashes**: retained for 90 days for abuse detection\n\n## 7. Your rights\n\nDepending on where you live (EU: GDPR, India: DPDPA, California: CCPA), you may have rights to:\n\n- **Access** — request a copy of the data we hold about you\n- **Rectify** — ask us to correct inaccurate data\n- **Erase** — ask us to delete your data (\"right to be forgotten\")\n- **Object** — object to certain processing\n- **Data portability** — receive your data in a machine-readable format\n\nEmail [YOUR SUPPORT EMAIL] to exercise any of these rights. We will respond within 30 days.\n\n## 8. Security\n\nWe use TLS on every connection, hash sensitive identifiers (IPs, admin passwords) before storing them, and rate-limit endpoints that could be brute-forced. Payment data goes directly to Razorpay/Stripe — it never touches our servers.\n\nNo system is 100% secure. If we ever discover a breach affecting your data we will notify you as soon as required by applicable law.\n\n## 9. International transfers\n\nIf you are outside [YOUR JURISDICTION] and interact with the Service, your data will be transferred to and processed in [YOUR JURISDICTION]. By using the Service you consent to this transfer.\n\n## 10. Children\n\nThe Service is not directed at children under 16. We do not knowingly collect data from anyone under 16.\n\n## 11. Changes\n\nWhen we update this policy the \"Last updated\" date at the top changes. Material changes will be announced via email to registered users where possible.\n\n## 12. Contact\n\nQuestions or requests: [YOUR SUPPORT EMAIL] · [YOUR POSTAL ADDRESS if required]."
}'
WHERE NOT EXISTS (SELECT 1 FROM portfolio_content WHERE section_key = 'legal.privacy');

INSERT INTO portfolio_content (section_key, label, body)
SELECT 'legal.refund', 'Legal — Refund Policy', '{
  "title": "Refund Policy",
  "lastUpdated": "2026-01-01",
  "body": "**This policy is a template.** Edit under /admin/portfolio → Legal → Refund before your first sale.\n\n## Overview\n\nAll products sold via [YOUR DOMAIN] are **digital source-code products** delivered instantly upon successful payment. Because the buyer receives the full source code — which cannot be \"returned\" — we operate a **strict no-refund policy** except in the specific circumstances listed below.\n\n## When refunds ARE issued\n\nWe will issue a **full refund** within 7 business days if any of the following apply:\n\n- **Duplicate charge** — you were charged twice for the same order due to a payment gateway or network error\n- **Order not delivered** — you paid but never received the download link email, and no download activity is recorded against your order within 48 hours of purchase\n- **Product materially defective** — the source code fails to build / run in the documented environment and we cannot resolve the issue within 7 days of you reporting it in writing\n- **Applicable consumer-law protection** — if a specific right to withdraw applies under your local law (e.g. EU 14-day cooling-off under limited circumstances, Indian Consumer Protection Act 2019), and you have not already downloaded the product\n\n## When refunds are NOT issued\n\n- **Change of mind** — after purchase, if the product is not what you expected\n- **You already downloaded** — once you have downloaded the product, no refund is available\n- **Not compatible with your stack** — always check the product description + tech stack listed before buying\n- **You could not integrate / customise the code** — support beyond the product itself is not included unless explicitly bundled\n- **Time has passed** — refund requests submitted more than 7 days after purchase\n\n## How to request a refund\n\nEmail [YOUR SUPPORT EMAIL] with:\n\n- Your order number (in the confirmation email)\n- The email address you used at checkout\n- A clear description of why you are requesting a refund\n- Any supporting screenshots or error messages\n\nWe will acknowledge your request within 2 business days and respond with a decision within 7 business days.\n\n## Chargebacks\n\nIf you file a chargeback with your bank or card issuer instead of contacting us first, we will contest it with the payment processor and provide evidence of delivery. Chargebacks filed without contacting us first may result in your email being blocked from future purchases.\n\nIf the chargeback is upheld and the product has been downloaded, we reserve the right to pursue the recovery of the funds through any available legal channel.\n\n## Processing time\n\nApproved refunds are issued to the original payment method within **7 business days** of approval. Banks may take an additional 5-10 business days to reflect the credit on your statement, depending on your card issuer.\n\n## Contact\n\nAny refund question: [YOUR SUPPORT EMAIL]"
}'
WHERE NOT EXISTS (SELECT 1 FROM portfolio_content WHERE section_key = 'legal.refund');
